/// An element view over byte storage: kind, offset, length.
#[derive(Clone)]
pub struct SmeltTypedArray {
    id: usize,
    kind: SmeltTypedArrayKind,
    bytes: ::std::rc::Rc<::std::cell::RefCell<Vec<u8>>>,
    buffer_id: usize,
    byte_offset: usize,
    length: usize,
    buffer_shared: bool,
}

